\title{The Exact Domination Number of the Path,\\ and a Program Toward Transmission Zero Forcing on Trees}
\author{Aristotle}
\date{2026-06-27}

\begin{document}
\maketitle

\begin{abstract}
We give a complete, gap-free determination of the domination number of the path graph $P_n$, the canonical infinite family of trees:
\[
\gamma(P_n) = \left\lceil \frac{n}{3} \right\rceil = \left\lfloor \frac{n+2}{3} \right\rfloor.
\]
Two developments are presented and reconciled. First, a self-contained \emph{combinatorial} model on the natural numbers, in which dominating sets of the path are subsets $S \subseteq \{0,\dots,n-1\}$ such that every vertex lies within graph distance one of $S$; here the domination number is computed exactly via a counting lower bound ($n \le 3\,|S|$ for every dominating set $S$) and an explicit optimal construction. Second, a \emph{genuine graph-theoretic} definition of the domination number for an arbitrary finite simple graph, together with a cardinality-preserving bridge proving that the domination number of the standard path graph coincides with the combinatorial quantity, hence equals $\lceil n/3\rceil$. The lower bound is exactly the maximum-degree bound $\gamma(G) \ge n/(\Delta+1)$ specialized to $\Delta = 2$, isolated as a reusable kernel. We then situate this result inside a research program: ordinary zero forcing satisfies $Z(P_n) = 1$ for all $n$, so it is decisively separated from domination; we conjecture that a distance-throttled variant --- the \emph{transmission zero forcing number} $\xi_T$ --- satisfies $\xi_T(T) = \gamma(T)$ for every tree $T$, with the path as the first milestone and the conjectured extremal case.
\end{abstract}

\section{Introduction}

Given a finite simple graph $G=(V,E)$, a set $D \subseteq V$ is a \emph{dominating set} if every vertex is either in $D$ or adjacent to a vertex of $D$. The \emph{domination number} $\gamma(G)$ is the minimum cardinality of a dominating set. The notion models a recurring optimization principle---cover an entire structure using as few resources as possible---and arises in facility location, fault monitoring, sensor placement, and the analysis of influence in networks.

For the path graph $P_n$ on vertices $\{0,1,\dots,n-1\}$ with edges between consecutive integers, the domination number is classically reported as $\lceil n/3 \rceil$. Our purpose is threefold: (1) to establish $\gamma(P_n) = \lceil n/3 \rceil$ with full rigor and reusable components; (2) to make precise the sharp \emph{non}-relationship between domination and ordinary zero forcing on paths; and (3) to articulate a conjectural framework in which a \emph{transmission-weighted} variant of zero forcing coincides with domination on trees. Throughout, $\lceil n/3 \rceil = \lfloor (n+2)/3 \rfloor$, and we use the integer-division expression $(n+2)/3$ for $\lceil n/3 \rceil$.

\section{A combinatorial model of domination on the path}

We model the vertex set of $P_n$ as $\{0,1,\dots,n-1\}$ and the closed-neighborhood relation as ``distance at most one.''

\begin{definition}[Dominating set of the path]
For $n \in \mathbb{N}$ and a finite $S \subseteq \mathbb{N}$, $S$ \emph{dominates} $P_n$, written $\DominatesPath\,n\,S$, when
\[
S \subseteq \{0,\dots,n-1\} \quad\text{and}\quad \forall i<n,\ \exists s \in S,\ (i \le s+1 \ \wedge\ s \le i+1).
\]
The conjunction $i \le s+1 \wedge s \le i+1$ is exactly $|i-s|\le 1$ over $\mathbb{N}$; using two linear inequalities keeps all metric reasoning inside linear integer arithmetic.
\end{definition}

\begin{definition}[Combinatorial domination number]
\[
\gamma(P_n) := \inf\{\, k \in \mathbb{N} \mid \exists S,\ \DominatesPath\,n\,S \ \wedge\ |S| = k \,\}.
\]
\end{definition}

\begin{definition}[Closed neighborhood block]
For $s \in \mathbb{N}$ let $\block(s) := \{s-1,s,s+1\} = [s-1,s+1]\cap\mathbb{N}$, of cardinality at most $3$.
\end{definition}

\begin{lemma}[Existence]\label{lem:exist}
The full vertex set dominates: $\DominatesPath\,n\,\{0,\dots,n-1\}$; hence $\gamma(P_n)$ is well-defined.
\end{lemma}
\begin{proof}
The full set is a subset of itself, and each $i<n$ is dominated by $s=i$.
\end{proof}

\subsection{The counting lower bound}

\begin{theorem}[Counting lower bound]\label{thm:lower}
If $S$ dominates $P_n$, then $n \le 3\,|S|$.
\end{theorem}
\begin{proof}
We claim $\{0,\dots,n-1\} \subseteq \bigcup_{s\in S}\block(s)$: for $i<n$, domination gives $s\in S$ with $|i-s|\le 1$, i.e. $i\in\block(s)$. Then
\[
n = |\{0,\dots,n-1\}| \le \Big|\bigcup_{s\in S}\block(s)\Big| \le \sum_{s\in S}|\block(s)| \le \sum_{s\in S}3 = 3\,|S|,
\]
by monotonicity of cardinality, subadditivity over a finite union, and $|\block(s)|\le 3$.
\end{proof}

\begin{remark}[Degree bound]
Theorem~\ref{thm:lower} is the $\Delta=2$ case of $\gamma(G)\ge n/(\Delta+1)$ for any $n$-vertex graph of maximum degree $\Delta$, proved identically with $\block(s)$ replaced by the closed neighborhood $N[s]$ (size $\le \Delta+1$).
\end{remark}

\subsection{The optimal construction}

\begin{definition}[Guard construction]
\[
\domc(n) := \big\{\,\min(3k+1,\,n-1) \ \big|\ k < \lceil n/3\rceil\,\big\},
\]
the image of $\{0,\dots,\lceil n/3\rceil-1\}$ under $k\mapsto \min(3k+1,n-1)$: a guard near the center of each consecutive triple, clamped at the last vertex.
\end{definition}

\begin{theorem}[The construction dominates]\label{thm:constr}
$\DominatesPath\,n\,(\domc(n))$.
\end{theorem}
\begin{proof}
Each element is $\le n-1<n$, giving the subset condition. For $i<n$, take $k=\lfloor i/3\rfloor < \lceil n/3\rceil$; the guard $s=\min(3k+1,n-1)$ satisfies $|i-s|\le 1$ in all residue cases $i=3k+r$, $r\in\{0,1,2\}$, clamping only moving the guard toward $i$. All obligations are linear arithmetic.
\end{proof}

\begin{theorem}[Cardinality]\label{thm:card}
$|\domc(n)| \le \lceil n/3\rceil$.
\end{theorem}
\begin{proof}
An image has cardinality at most that of its domain, $\lceil n/3\rceil$; clamping only identifies elements, lowering the count.
\end{proof}

\subsection{The exact value}

\begin{theorem}[Domination number of the path]\label{thm:main}
For all $n\in\mathbb{N}$,
\[
\gamma(P_n) = \left\lceil \frac{n}{3}\right\rceil = \frac{n+2}{3}\ \text{(integer division)}.
\]
\end{theorem}
\begin{proof}
\emph{Upper bound:} by Theorems~\ref{thm:constr} and~\ref{thm:card}, $\domc(n)$ is a dominating set of size $\le \lceil n/3\rceil$, so $\gamma(P_n)\le \lceil n/3\rceil$. \emph{Lower bound:} $\gamma(P_n)$ is attained by some dominating $S$ (Lemma~\ref{lem:exist} and well-ordering); Theorem~\ref{thm:lower} gives $n\le 3|S|=3\gamma(P_n)$, so $\gamma(P_n)\ge \lceil n/3\rceil$. Antisymmetry concludes.
\end{proof}

\section{The graph-theoretic domination number and the bridge}

\begin{definition}[Dominating set of a graph]
For a simple graph $G$ on $V$ and finite $D\subseteq V$, $\IsDom\,G\,D$ holds when
$\forall v\in V,\ v\in D \ \vee\ \exists d\in D,\ G.\Adj\,d\,v.$
\end{definition}

\begin{definition}[Domination number]
For finite $G$, $\gamma(G)$ is the least cardinality of a dominating set $D\subseteq V$.
\end{definition}

\begin{theorem}[Bridge to the standard path graph]\label{thm:bridge}
$\gamma(\pathGraph\,n) = \gamma(P_n)$ (combinatorial value).
\end{theorem}
\begin{proof}[Proof sketch]
Transport dominating sets across encodings preserving cardinality. A combinatorial $S\subseteq\{0,\dots,n-1\}$ maps to a vertex set of $\pathGraph\,n$ by attaching the bound $i<n$; conversely forget the bound. Adjacency in $\pathGraph\,n$ is exactly $|i-j|=1$, so closed-neighborhood membership matches distance $\le 1$. Both maps preserve cardinality, so the minima agree. The only technical care is reducing the projection of a bounded vertex to its integer before arithmetic.
\end{proof}

\begin{corollary}\label{cor:graphval}
$\gamma(\pathGraph\,n) = \lceil n/3\rceil = (n+2)/3.$
\end{corollary}
\begin{proof}
Combine Theorem~\ref{thm:bridge} and Theorem~\ref{thm:main}.
\end{proof}

\section{Separation from zero forcing}

\begin{definition}[Zero forcing]
Color vertices blue/white. \emph{Color-change rule:} a blue vertex with exactly one white neighbor forces that neighbor blue. $B\subseteq V$ is a \emph{zero forcing set} if starting from $B$ blue and applying the rule to closure turns all of $V$ blue. $Z(G)$ is the minimum size of such a set.
\end{definition}

\begin{proposition}[Zero forcing of the path]\label{prop:zf}
$Z(P_n)=1$ for every $n\ge 1$.
\end{proposition}
\begin{proof}
Color vertex $0$ blue; the unique frontier vertex always has exactly one white neighbor, so blue advances one vertex at a time until all of $P_n$ is blue. One seed suffices and at least one is necessary.
\end{proof}

\begin{corollary}[Sharp separation]
For $n\ge 4$, $Z(P_n)=1 < \lceil n/3\rceil = \gamma(P_n)$, with gap $\to\infty$. Ordinary zero forcing cannot equal domination on paths.
\end{corollary}

Exhaustive enumeration over $P_1,\dots,P_9$ confirms $\gamma=(1,1,1,2,2,2,3,3,3)$ and $Z=(1,\dots,1)$.

\section{The transmission zero forcing program}

\begin{definition}[Transmission zero forcing number, informal]
$\xi_T(G)$ is the minimum, over zero forcing sets $B$, of the number of \emph{transmission-bounded} forces---equivalently the minimum size of a set that both zero-forces and dominates $G$ (each force covering distance $\le 1$). Throttling forbids the single-seed cascade on $P_n$, so admissible sets coincide with dominating sets.
\end{definition}

\begin{conjecture}[Headline: forcing equals domination on trees]
For every tree $T$, $\xi_T(T)=\gamma(T)$. First milestone: $\xi_T(P_n)=\lceil n/3\rceil$, via identifying throttled forcing sets with dominating sets and Theorem~\ref{thm:main}.
\end{conjecture}

\begin{conjecture}[Stars and spiders]
$\gamma(K_{1,m})=1$ for $m\ge 1$; for the spider with $k$ legs of length $\ell$, $\gamma = k\lfloor\ell/3\rfloor + c$ with $c\in\{0,1\}$. Method: replay the counting-plus-construction template.
\end{conjecture}

\begin{conjecture}[Sharp degree bound]
For every $n$-vertex $G$ of max degree $\Delta$, $\gamma(G)\ge n/(\Delta+1)$, with equality iff $D$ is a perfect code. Method: the union bound over closed neighborhoods generalizing Theorem~\ref{thm:lower}.
\end{conjecture}

\begin{conjecture}[Path is extremal among trees]
Among trees on $n$ vertices, $\gamma(T)\le \lceil n/3\rceil$, with equality iff $T$ is a caterpillar of $P_3$'s. Method: induction peeling a longest path.
\end{conjecture}

\begin{conjecture}[Tribonacci recurrence]
The domination polynomials satisfy $D(P_n)=D(P_{n-1})+D(P_{n-2})+D(P_{n-3})$, reflecting the size-$3$ closed neighborhood.
\end{conjecture}

\section{Algorithms and computational evidence}

\textbf{Algorithm A (brute-force $\gamma$).} For $k=0,1,2,\dots$, enumerate all $\binom{n}{k}$ subsets and test domination; return the first feasible $k$. Time $O(2^n n^2)$; certifies $\gamma(P_n)$ for small $n$.

\smallskip
\textbf{Algorithm B (clamped path construction).} Emit $\min(3k+1,n-1)$ for $k=0,\dots,\lceil n/3\rceil-1$ and deduplicate. Time $O(n)$; realizes an optimal dominating set.

\smallskip
Enumeration over $P_1,\dots,P_9$ yields $\gamma=1,1,1,2,2,2,3,3,3=\lceil n/3\rceil$ and $Z=1$ throughout.

\section{Discussion and future work}

The value is elementary, but its establishment yields durable infrastructure: a general definition of $\gamma$, a counting kernel (the $\Delta=2$ face of a universal degree bound), a construction template needing only existence of a small set, and a cardinality-preserving bridge between a computation-friendly model and a library-standard graph. The conceptual payload is the sharp separation $Z(P_n)=1$ vs. $\gamma(P_n)=\lceil n/3\rceil$, motivating distance-throttling. The headline conjecture $\xi_T(T)=\gamma(T)$ for trees is the organizing goal; the path is its first milestone and conjectured extremal anchor. Next cycles target the star/spider closed form and the path milestone of the headline conjecture, then the general degree bound, the tribonacci recurrence, and finally path extremality and the full equality across trees.

\end{document}

