    ground-truth checker against the closed form ceil(n/3)."""
    if n == 0:
        return 0
    verts: List[int] = list(range(n))
    for k in range(n + 1):
        for combo in combinations(verts, k):
            if dominates_path(n, frozenset(combo)):
                return k
    return n

